-- Kho thực phẩm Viện Dinh dưỡng 2025, số trên 100 g phần ăn được, để tìm bằng kính lúp ở màn thêm món
CREATE TABLE thuc_pham (
  id SERIAL PRIMARY KEY,
  -- Mã của thực phẩm trên trang Viện Dinh dưỡng (cùng cách đánh mã với bảng 2007), ví dụ 2008002
  ma_so TEXT NOT NULL UNIQUE,
  ten_thuc_pham TEXT NOT NULL,
  -- Tên bỏ dấu, bỏ dấu phẩy, chữ thường, để gõ "khoai lang luoc" cũng tìm ra "Khoai lang, luộc"
  ten_khong_dau TEXT NOT NULL,
  kcal_100g NUMERIC(6, 1) NOT NULL CHECK (kcal_100g >= 0),
  -- Chất Viện chưa có số thì để trống, không ghi 0
  dam_100g NUMERIC(7, 2) CHECK (dam_100g >= 0),
  tinh_bot_100g NUMERIC(7, 2) CHECK (tinh_bot_100g >= 0),
  beo_100g NUMERIC(7, 2) CHECK (beo_100g >= 0),
  -- Muối quy từ natri: natri 2000 mg tương đương muối 5 g (Viện Dinh dưỡng, Tra cứu nhu cầu dinh dưỡng, tra ngày 08/10/2026)
  muoi_100g NUMERIC(7, 2) CHECK (muoi_100g >= 0),
  duong_100g NUMERIC(7, 2) CHECK (duong_100g >= 0),
  beo_no_100g NUMERIC(7, 2) CHECK (beo_no_100g >= 0),
  -- 10 chất chỉ để xem ở "Xem đủ chất" (King chốt 02/11/2026): nước (g), chất xơ (g), canxi, kali, magie, sắt (mg), vitamin A, RAE (µg), C (mg), D, D2 + D3 (µg), E (mg)
  nuoc_100g NUMERIC(9, 2) CHECK (nuoc_100g >= 0),
  chat_xo_100g NUMERIC(9, 2) CHECK (chat_xo_100g >= 0),
  canxi_mg_100g NUMERIC(9, 2) CHECK (canxi_mg_100g >= 0),
  kali_mg_100g NUMERIC(9, 2) CHECK (kali_mg_100g >= 0),
  magie_mg_100g NUMERIC(9, 2) CHECK (magie_mg_100g >= 0),
  sat_mg_100g NUMERIC(9, 2) CHECK (sat_mg_100g >= 0),
  vitamin_a_mcg_100g NUMERIC(9, 2) CHECK (vitamin_a_mcg_100g >= 0),
  vitamin_c_mg_100g NUMERIC(9, 2) CHECK (vitamin_c_mg_100g >= 0),
  vitamin_d_mcg_100g NUMERIC(9, 2) CHECK (vitamin_d_mcg_100g >= 0),
  vitamin_e_mg_100g NUMERIC(9, 2) CHECK (vitamin_e_mg_100g >= 0),
  nguon TEXT NOT NULL,
  lien_ket TEXT NOT NULL,
  ngay_hieu_luc DATE NOT NULL,
  -- Mỗi dòng thiếu nhiều nhất 1 trong 3 chất đạm, tinh bột, béo
  CHECK (num_nulls(dam_100g, tinh_bot_100g, beo_100g) <= 1)
);

-- Chép 793 thực phẩm ngày 21/10/2026, chỉ giữ thực phẩm đơn ăn được ngay (bỏ thịt chó, dòng trùng, đồ phải nấu, gia vị, món nấu sẵn, thứ trùng Món của Viện), còn 477; tên thịt ghi lại theo một kiểu, không đổi số nào (NguonSoLieu.md)
